        double pesoTotal = calcularPesoTotal(request.getItens());
        Entrega entrega = Entrega.obter(request.getModalidadeEntrega());
        double frete = 0.0;
        if (entrega != null) {
            frete = entrega.calcularFrete(pesoTotal);
        }

        return subtotal - desconto + frete;
    }

}

